WITH sales_item AS (SELECT ws_item_sk AS item_sk, SUM(ws_quantity) AS total_sold_qty, SUM(ws_ext_sales_price) AS total_sold_amount, SUM(ws_net_profit) AS total_sales_profit FROM web_sales GROUP BY ws_item_sk), returns_item AS (SELECT cr_item_sk AS item_sk, SUM(cr_return_quantity) AS total_return_qty, SUM(cr_return_amt_inc_tax) AS total_return_amount, SUM(cr_net_loss) AS total_return_loss FROM catalog_returns GROUP BY cr_item_sk) SELECT si.item_sk, si.total_sold_qty, ri.total_return_qty, CASE WHEN si.total_sold_qty = 0 THEN 0 ELSE (ri.total_return_qty * 1.0) / si.total_sold_qty END AS return_rate, (si.total_sales_profit - COALESCE(ri.total_return_loss, 0)) AS net_item_profit, CASE WHEN (si.total_sales_profit - COALESCE(ri.total_return_loss, 0)) > 0 THEN 'Profitable' ELSE 'Unprofitable' END AS profitability_flag, DENSE_RANK() OVER (ORDER BY CASE WHEN si.total_sold_qty = 0 THEN 0 ELSE (ri.total_return_qty * 1.0) / si.total_sold_qty END DESC) AS return_rate_rank, ROW_NUMBER() OVER (ORDER BY (si.total_sales_profit - COALESCE(ri.total_return_loss, 0)) DESC) AS profit_rank FROM sales_item si LEFT JOIN returns_item ri ON si.item_sk = ri.item_sk WHERE si.total_sold_qty > 0 ORDER BY return_rate DESC LIMIT 20
